<?php 
    $sources=$db->query('SELECT p.*, (SELECT COUNT(*) FROM articles a WHERE a.source_id=p.id) AS total FROM editorial_sources p ORDER BY name')->fetchAll();
    $editId=(int)($_GET['id']??0);$editing=null;
    foreach($sources as $src)if((int)$src['id']===$editId)$editing=$src; ?>
    <div class="panel"><div class="panel-heading"><h2>Fontes cadastradas</h2><span class="muted tiny">Links de referência das matérias</span></div><div class="table-wrap"><table><thead><tr><th>Fonte</th><th>Vínculos</th><th>Ações</th></tr></thead><tbody><?php foreach($sources as $src): ?><tr><td><strong><?= h($src['name']) ?></strong><small class="caption-hint source-domain"><?= h((string)(parse_url((string)($src['url']??''),PHP_URL_HOST) ?: 'Sem endereço cadastrado')) ?></small><?php if(!empty($src['url'])): ?><details class="compact-help source-link-help"><summary aria-label="Ver endereço completo da fonte" title="Ver endereço completo">?</summary><div class="compact-help-content"><code><?=h($src['url'])?></code></div></details><?php endif; ?></td><td><?= (int)$src['total'] ?></td><td class="action-cell"><a href="<?= h(admin_link('sources')) ?>&id=<?= (int)$src['id'] ?>#edit-source">Editar</a><form method="post" action="<?= h(admin_link('delete_source')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$src['id'] ?>"><button class="danger-link" data-confirm="Remover fonte do catálogo? Referências textuais antigas serão mantidas.">Remover</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
    <div class="panel form-panel" id="edit-source"><h2><?= $editing?'Editar fonte':'Nova fonte' ?></h2><form method="post" action="<?= h(admin_link('save_source')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><div class="form-grid"><label>Nome da fonte<input name="name" maxlength="160" required value="<?= h($editing['name']??'') ?>"></label><label class="full">Site / link HTTPS<input name="url" type="url" maxlength="600" placeholder="https://..." value="<?= h($editing['url']??'') ?>"></label></div><button class="btn primary">Salvar fonte</button></form></div>
